begin;
select plan(14);
select sync_mark_history_assets('[{"asset":"MARK_A","dex":""},{"asset":"MARK_B","dex":"xyz"}]');
select merge_mark_observations(a.asset,(select jsonb_agg(jsonb_build_object('time',extract(epoch from now()-make_interval(mins=>h)-interval '15 seconds')*1000,'price','100.123456789')) from unnest(array[5,10,30,60,360,1440,10080])h),'0xarchive_mark') from mark_history_assets a;
select is((refresh_mark_reference_coverage()->>'total')::integer,14,'every window on every asset is audited');
select is((mark_reference_health()->>'ready')::integer,14,'all windows are ready without any watchlist membership');
select ok((select count(*)>0 from mark_archive_jobs),'approaching reference gaps are queued while current coverage is still complete');
insert into asset_analytics_cache(asset,price_history,history_updated_at) values('MARK_A','[{"time":1,"price":999}]',now());
select is((asset_mark_reference_snapshot()->'rows'->0->'mark_history'->0->>'price')::numeric,100.123456789::numeric,'trade cache cannot change a genuine mark reference');
select is(has_table_privilege('history_archive','paper_accounts','SELECT'),false,'archive collector has no financial account access');
select is(has_table_privilege('authenticated','mark_price_samples','INSERT'),false,'owner cannot forge mark samples');
select ok(not has_function_privilege('history_archive','public.apply_paper_effects(uuid,integer,bigint,text,jsonb)','EXECUTE'),'archive collector cannot execute paper effects');
select is(public.reserve_mark_archive_request(),true,'bounded archive work reserves one request');
update mark_archive_usage set requests=15000 where day=current_date;
select is(public.reserve_mark_archive_request(),false,'daily archive limit is enforced');
update mark_archive_usage set requests=1,credits_remaining=4999 where day=current_date;
select is(public.reserve_mark_archive_request(),false,'provider credit reserve is enforced');
update mark_archive_usage set credits_remaining=100000 where day=current_date;
insert into mark_archive_jobs(asset,band,start_ms,end_ms) values('MARK_A',5,1000,2000);
select ok(claim_mark_archive_job()->>'lease_token' is not null,'archive page claims are fenced');
select is(finish_mark_archive_page('MARK_A',5,extensions.gen_random_uuid(),'[]',null,null,0,100000),false,'expired or foreign lease cannot acknowledge a page');
select is((select count(*)::integer from mark_price_samples where observed_at>now()),0,'no reference observations look ahead');
delete from mark_price_samples where asset='MARK_B' and bucket=date_trunc('minute',now()-interval '5 minutes 15 seconds');
select refresh_mark_reference_coverage();
select is((mark_reference_health()->>'missing')::integer,1,'one missing non-favourite window is not hidden by overall liveness');
select * from finish();
rollback;
